WITH filtered AS (SELECT id, device_code, temp_c, humidity, pressure, ROUND(humidity, 1) humidity_rounded, LOWER(firmware) firmware_lower FROM device_readings WHERE temp_c IS NOT NULL) SELECT id, device_code, pressure, firmware_lower, SUM(pressure) OVER w_recent last3_sum_pressure, MIN(pressure) OVER w_recent last3_min_pressure, COUNT(pressure) OVER w_recent last3_count_pressure, ROW_NUMBER() OVER w_part seq_no FROM filtered WINDOW w_recent AS (PARTITION BY device_code ORDER BY temp_c, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW), w_part AS (PARTITION BY device_code ORDER BY pressure, id);
